def minimumRecolors(blocks: str, k: int) -> int:
    n = len(blocks)
    min_recolors = float('inf')
    white_count = 0

    # Count whites in the first window
    for i in range(k):
        if blocks[i] == 'W':
            white_count += 1
    min_recolors = white_count

    # Slide the window
    for i in range(k, n):
        # Remove leftmost
        if blocks[i - k] == 'W':
            white_count -= 1
        # Add new rightmost
        if blocks[i] == 'W':
            white_count += 1
        if white_count < min_recolors:
            min_recolors = white_count

    return min_recolors
